// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // The reference contract's transferOwnership reverts for zero address; the mutant does not.
        // We call transferOwnership(address(0)) and catch whether it reverts.
        vm.prank(address(this)); // owner is deployer (address(this))
        bool ok;
        try c.transferOwnership(address(0)) {
            ok = true;
        } catch {
            ok = false;
        }
        // In the reference, ok is false (revert); in the mutant, ok is true.
        assertTrue(ok, "reference should revert, bug should succeed");
    }
}

