pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Attempt to transfer ownership to address(0)
        // Reference: reverts (require newOwner != address(0))
        // Mutant: succeeds, owner becomes address(0)
        // After call, owner() check diverges

        // Capture whether the call reverts
        bool ok;
        try c.transferOwnership(address(0)) {
            ok = true;
        } catch {
            ok = false;
        }
        // On reference: call reverts => ok = false
        // On mutant: call succeeds => ok = true
        // Additionally, check owner() after attempt:
        // On reference, owner() == address(this) (unchanged)
        // On mutant, owner() == address(0)
        address ownerAfter = c.owner();
        // The reference satisfies: ok == false && ownerAfter != address(0)
        // The buggy version breaks: ok == true && ownerAfter == address(0)
        // Assert the reference property
        assertTrue(ok == false && ownerAfter != address(0), "Reference: transferOwnership to zero should revert and owner unchanged; buggy would succeed and set owner to zero");
    }
}

