pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Transfer ownership to zero address via transferOwnership
        // Reference: require(newOwner == address(0)) allows it
        // Mutant: require(newOwner == address(0)) also allows it, but original require(newOwner != address(0)) reverts
        vm.prank(address(this));
        c.transferOwnership(address(0));

        // In reference, this should have reverted (so ownership unchanged, owner is address(this))
        // In mutant, ownership changed to address(0)
        // Check that owner() returns address(0) — that's the bug
        assertTrue(c.owner() == address(0));
    }
}

