pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // The deployer is owner. Try to transfer ownership to address(0).
        // In reference: requires newOwner != address(0) -> reverts.
        // In mutant: requires newOwner == address(0) -> succeeds, owner becomes zero.
        // We catch the revert to observe difference.
        bool refReverted = false;
        vm.prank(address(this));
        try c.transferOwnership(address(0)) {
            // mutant path: no revert, owner becomes zero
        } catch {
            refReverted = true;
        }
        // For the reference, it reverts. For the mutant, it doesn't.
        // Now try to call allowance(address(0), address(0)) to invoke owner() getter (via Ownable check? No, allowance doesn't use owner). Instead, we read owner() directly.
        // But owner() is a public view, so we can call c.owner(). For reference it would revert? No, owner() just returns _owner, no require. So after reference revert, owner() still returns the original owner. After mutant success, owner() returns zero.
        // We need a different observable divergence. Let's try calling a function that uses onlyOwner modifier, e.g., setCaller, after ownership changed.
        // For reference: ownership never changed, so setCaller works. For mutant: owner is zero, so setCaller reverts because _checkOwner() fails (owner() != msg.sender).
        vm.prank(address(this));
        bool setCallerReverted = false;
        try c.setCaller(address(0x123)) {
        } catch {
            setCallerReverted = true;
        }
        // In reference: no revert, so setCallerReverted == false. In mutant: revert because owner is zero, so setCallerReverted == true.
        assertTrue(setCallerReverted == true);
    }
}

