// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Call transferOwnership(address(0)) as owner
        vm.prank(address(this));
        (bool success, ) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", address(0)));
        // Now call allowance with the owner (which would be address(0) if mutant succeeded, or revert if not)
        address owner;
        if (success) {
            // mutant: transferOwnership succeeded; owner is now address(0)
            owner = address(0);
        } else {
            // reference: transferOwnership reverted; owner is still this contract
            owner = address(this);
        }
        // Read allowance(owner, address(0)). In reference it succeeds (owner non-zero), in mutant it succeeds too (owner zero is okay for allowance view).
        // But we need a divergence: after transferOwnership(address(0)) reverts in reference, owner is still original; after it succeeds in mutant, owner is zero.
        // Calling owner() getter:
        address o = c.owner();
        assertTrue(o == address(0)); // reference reverts at transferOwnership, so o != 0; if mutant succeeds, o == 0. So this assertion passes on mutant, fails on reference.
    }
}

