pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Setup: transfer some tokens to an EOA (address(1)) and then to the pair
        address user = address(1);
        // Constructor mints 2e24 wei to msg.sender (address(this)). Transfer 1000 tokens to user
        vm.prank(address(this));
        c.transfer(user, 1000e18);
        // Now user sells to the pair (simulate a swap by transferring to pairAddress)
        vm.prank(user);
        c.transfer(c.pairAddress(), 100e18);
        // Check decimals via the token itself — reference returns 18, bug returns 6
        bool ok;
        try c.decimals() returns (uint8 d) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference (decimals=18) will return successfully, but the bug (decimals=6) will NOT revert — they both return. However, the observable difference is that the bug's return value is 6, not 18. So we assert that decimals() returns 18.
        assertEq(c.decimals(), 18);
    }
}

