pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up: make this contract the cfo and owner, add liquidity via helper
        vm.startPrank(address(this));
        // Approve USDT for router (we use mock addresses but router is real)
        // Deploy a mock USDT, but we can't import new contracts. Instead, we use the addresses defined in C.
        // Since the test runs on forked mainnet or with mocks, we'll use the actual BSC addresses (they exist on mainnet fork)
        // For simplicity, we'll simulate the scenario by directly minting tokens and manipulating state via the public setters.
        // The key: after a sell, totalSupply decreases by deadAmount which is (amount - fee)/deadCfg.
        // The bug is decimals() returning 6 vs 18, but decimals() is not used in _transfer directly.
        // However, the burnPair uses _burn which calls _beforeTokenTransfer which is empty.
        // The actual observable difference is that the buggy contract's decimals() returns 6.
        // We assert directly: c.decimals() == 18 for reference, != 18 for bug.
        vm.stopPrank();
        assertTrue(c.decimals() == 18, "decimals should be 18");
    }
}

