// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Step 1: Get the initial totalSupply (should be 2000000 * 1e18 = 2_000_000e18)
        uint256 initialSupply = c.totalSupply();

        // Step 2: The owner (address(this)) has all tokens. We need to trigger a sell on the pair.
        // But first we must set up the pair and make sure there is liquidity.
        // The contract creates a pair with USDT, but we don't have USDT. We'll just use the fact
        // that the constructor mints all tokens to the owner and sets whiteAddress[msg.sender] = true.
        // The _transfer in C has a special condition: if (from == pairAddress) it reverts with "buy error".
        // And if (to == pairAddress && !swapping) it takes a fee and burns. 
        // Since we cannot actually call the Uniswap router (we don't have tokens), we must 
        // directly call a transfer to the pairAddress to trigger the burn logic.
        // But the burn logic requires the `swapping` flag to be false, which it is initially.
        // Also it calls swapTokensForUSDT which needs approval and router. 
        // To simplify, we can just call burnPair indirectly via a transfer to pairAddress,
        // but the `swapping` flag will be set to true during the process. 
        // Actually the logic only does the fee/burn when `msg.sender == router` after the fee transfer.
        // Since we are not the router, the inner part (swapTokensForUSDT) won't execute.
        // So the transfer will: take fee, then check `if (msg.sender == router)` which is false, skip swap,
        // then set swapping = false, then if (balanceOf(pairAddress) > deadAmount) burnPair.
        // At this point pairAddress has 0 balance because we never minted to it.
        // So burnPair won't execute because balanceOf(pairAddress) == 0 <= deadAmount.

        // Let's mint some tokens to the pairAddress directly to cause a burn.
        // We can't mint directly, but we can transfer tokens to pairAddress.
        // However transfers to pairAddress will trigger the fee logic again. We'll do a white-listed transfer first?
        // The owner is whitelisted, so if we call super._transfer directly? No, we can't override internal.
        // Alternative: we call the public transfer function. Since owner is whitelisted, _transfer returns immediately.
        // So we can transfer from owner (address(this)) to pairAddress via public transfer, which will bypass the fee logic.

        // Actually the whiteAddress check: `if (amount == 0 || whiteAddress[from] || whiteAddress[to]) { super._transfer(...); return; }`
        // Since owner is whitelisted as `from`, the transfer to pairAddress will just do a normal transfer.
        // So after that, pairAddress will have some tokens.
        uint256 amountToPair = 1000 * 1e18;
        c.transfer(address(c.pairAddress()), amountToPair);

        // Now we need to trigger a transfer from a non-whitelisted address to pairAddress 
        // to cause the fee and burn logic to run. Let's create a user and give them tokens.
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        // user has no tokens; we need to transfer some from owner to user first.
        // But owner to user is whitelisted (owner is white), so that's fine.
        c.transfer(user, 500 * 1e18);

        // Now user transfers to pairAddress. This should trigger the fee and burn.
        uint256 oldTotalSupply = c.totalSupply();
        vm.prank(user);
        c.transfer(address(c.pairAddress()), 200 * 1e18);

        // The transfer should have: taken 5% fee (10e18) to contract, then the rest (190e18) to pairAddress.
        // Then the condition `if (to == pairAddress && !swapping)` is true, so swapping becomes true.
        // Then it takes fee, transfers it to address(this), then checks `if (msg.sender == router)`
        // Since user is not router, the inner if is skipped. swapping = false.
        // Then if (balanceOf(pairAddress) > deadAmount) where deadAmount = (amount - fee)/deadCfg = (200-10)/2 = 95e18.
        // At this point pairAddress had previous balance (1000e18) plus received (190e18) = 1190e18 which is > 95e18, so burnPair(95e18) is called.
        // This burns 95e18 from pairAddress, reducing totalSupply by 95e18.

        uint256 newTotalSupply = c.totalSupply();
        // In the reference: totalSupply decreases by 95e18. In the mutant: totalSupply = _totalSupply + 1, so the decrease is masked? 
        // Actually the mutant returns _totalSupply + 1. So if _totalSupply = oldTotalSupply - 95e18, the mutant returns that value + 1.
