        bool ok;
        try c.transferFrom(alice, bob, 1000) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: transferFrom returns false (insufficient balance 1999500 - 1000? wait, Alice still has 1999500, so it should succeed? Let's fix: start with Alice having only 500)
