        c.approve(bob, 1000);
        vm.prank(bob);
        try c.transferFrom(alice, bob, 1000) {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference, alice balance is 500 < 1000, so _transfer reverts => catch => ok = false
        // In mutant, _transfer(to, to, amount) does nothing and returns true => ok = true
